// Simplified LRU eviction implementation
// Evicts entries from the tail of the LRU list until target_usage is reached
while (usage_ > target_usage && !lru_list_.empty()) {
    // Get the least recently used entry (from the front of the list)
    auto it = lru_list_.begin();
    if (it != lru_list_.end()) {
        // Subtract the entry size from current usage
        usage_ -= it->charge;
        // Remove the entry from the cache
        cache_.erase(it->key);
        // Remove from LRU list
        lru_list_.pop_front();
    }
}

